// =========================================
// Reactive UI Update Function
// =========================================
function updateSubscribeButtons() {
  const state = window.$reactive.get("subscription");

  document.querySelectorAll(".subscribe-btn").forEach((btn) => {
    const textContent = btn.querySelector(".__text_block__");

    if (textContent) {
      if (state.isLoading) {
        textContent.textContent = "Loading...";
        btn.disabled = true;
        btn.style.opacity = "0.6";
        btn.style.cursor = "not-allowed";
      } else {
        textContent.textContent = state.isSubscribed
          ? "Subscribed"
          : "Subscribe";
        btn.disabled = false;
        btn.style.opacity = "1";
        btn.style.cursor = "pointer";
      }
    }

    // Show error state
    if (state.error && !state.isLoading) {
      btn.style.borderColor = "#ef4444";
      btn.style.borderWidth = "2px";
    } else {
      btn.style.borderColor = "";
      btn.style.borderWidth = "";
    }
  });
}

// =========================================
// Enhanced Reactive Subscribe Function
// =========================================
async function toggleSubscribe(publication) {
  const state = window.$reactive.get("subscription");

  // Set loading state
  window.$reactive.update("subscription", {
    isLoading: true,
    error: null,
  });

  try {
    const result = await frappeClient.post("Cafe Subscription", {
      publication: publication,
    });
    const isSubscribed = result.data.subscribed_by_me;
    const subscriberCount =
      result.data.subscriber_count || state.subscriberCount;

    // Update reactive state
    window.$reactive.update("subscription", {
      isSubscribed: isSubscribed,
      isLoading: false,
      error: null,
      subscriberCount: subscriberCount,
    });

    // Show success toast
    toast.success(
      isSubscribed ? "Successfully subscribed!" : "Unsubscribed successfully",
    );

    return result;
  } catch (error) {
    console.error("Error toggling subscription:", error);

    // Update reactive state with error
    window.$reactive.update("subscription", {
      isLoading: false,
      error: error.message,
    });

    // Show error toast
    toast.error(error.message || "Failed to update subscription");

    throw error;
  }
}

const initSubscription = () => {
  // Initialize reactive subscription state
  console.log("Initializing subscription state");
  const subscriptionState = window.$reactive.get("subscription") || {
    isSubscribed: window.page_data?.author?.is_subscribed || false,
    isLoading: false,
    error: null,
    subscriberCount: window.page_data?.author?.subscriber_count || 0,
  };

  window.$reactive.set("subscription", subscriptionState);

  window.$reactive.watch("subscription", () => {
    updateSubscribeButtons();
  });

  // Set initial button states
  updateSubscribeButtons();
};

if (!window.onPageLoad) {
  window.onPageLoad = [];
}

window.onPageLoad.push(initSubscription);

// Add click handlers to all subscribe buttons
document.querySelectorAll(".subscribe-btn").forEach((btn) => {
  btn.onclick = function () {
    toggleSubscribe(window.page_data.post.name);
  };
});
